def n(x):return f'{int(x):,}'.replace(',','.')
def pct(x,d=1):return f'{x*100:.{d}f}%'.replace('.',',')
def brl(x):return 'R$ '+f'{x:,.2f}'.replace(',','X').replace('.',',').replace('X','.')
def tab(df,pc=(),money=()):
 d=df.copy()
 for c in d:
  if c in pc:d[c]=d[c].map(lambda x:'—' if pd.isna(x) else pct(x,2))
  elif c in money:d[c]=d[c].map(lambda x:'—' if pd.isna(x) else brl(x))
  elif pd.api.types.is_float_dtype(d[c]):d[c]=d[c].map(lambda x:'—' if pd.isna(x) else f'{x:.4g}')
 return '<div class="table-wrap">'+d.to_html(index=False,border=0,classes='data-table')+'</div>'
def call(title,body,kind='teal'):return f'<aside class="callout {kind}"><b>{title}</b><p>{body}</p></aside>'
def evidence(source,scope):return f'<p class="evidence"><b>Evidência:</b> {source} · {scope}</p>'
