add('''<header class="hero" id="top"><span class="pill">DIAGNÓSTICO ANALÍTICO V1 · 19 OUT 2026</span><h1>VITALIZA | Customer Intelligence &amp; Retention — Diagnóstico Analítico V1</h1><p class="subtitle">MBA Inteli — Inteligência de Mercado e Modelagem Preditiva para Crescimento</p><div class="hero-line">Do comportamento observado à investigação estratégica.<br>Sem forçar o dado a confirmar a narrativa.</div><div class="hero-tags"><span>Dados até 30/09/2026</span><span>14 hipóteses</span><span>3 segmentos + cobertura insuficiente</span><span>Sem recomendação definitiva entre A e B</span></div></header>''')
begin('summary','01 · EXECUTIVE SUMMARY','O que mudou no diagnóstico?','Resultados calculados a partir dos anexos, com incerteza e escopo explícitos. A segmentação é exploratória; nenhum classificador de churn foi validado para uso operacional.')
add(f'''<div class="kpis"><div><small>PAGANTES NO CORTE</small><b>{n(M['corte_n'])}</b><span>60 cortesias excluídas.</span></div><div><small>MRR BRUTO EQUIVALENTE</small><b>{brl(M['mrr_proxy'])}</b><span>Proxy da última cobrança positiva.</span></div><div><small>CHURN EM SETEMBRO</small><b>4,99%</b><span>714 / 14.319 da base inicial.</span></div><div><small>SEGMENTAÇÃO</small><b>{M['K']} grupos</b><span>13.653 observações completas recentes.</span></div></div>''')
findings=[('1. O data room não reproduz os KPIs da aula.','14.753 pagantes e ARR equivalente de R$5,49 milhões, contra 27.901 e R$13,35 milhões no briefing. Antes de apresentar ao Conselho, reconciliar versão, universo e janela.','Financeiro + enunciado original; corte30/09.'),('2. “Abandono precoce” não é a explicação dominante na definição testada.','Entre 19.967 novos pagantes com 60 dias completos, 1,10% saem nos dias0–29; 5,03% dos sobreviventes saem nos dias30–59. Trial não entrou nessa comparação.','Intervalos por eventos; entradas01/2025–07/2026.'),('3. Desengajamento tem sinal, mas não é uma explicação causal pronta.','Queda de uso tem OR3,79 no modelo básico,2,74 com demais sinais e1,68 após incluir avisos de renovação. A associação se mantém; sua atenuação sugere informação sobreposta e/ou mediação, não prova causalidade.','14.032 pagantes no landmark de31/07; alvo60 observado.'),('4. Três perfis estáveis à reamostragem, sensíveis às features.','K3 foi escolhido por parcimônia dentro da faixa de silhouette da melhor solução elegível. ARI médio0,991; silhouette0,223. Incluir a dimensão redundante de dias ativos muda a partição(ARI0,444). Não foram usados churn, motivo de saída nem preço para criá-los.','13.653 usuários com uso recente disponível; cinco features.'),('5. Baixo uso prolongado é material, mas não prova “Sleeping Dogs”.','2.440 pagantes >180dias têm <0,5 sessão/semana em setembro; 1.015 repetem baixo uso em três meses. Não demonstramos que o contato os faz cancelar.','Corte30/09; sessões normalizadas por dias do mês.'),('6. Alcance do cancelamento no site é limitado.','1.118 de3.389 expirações de jun-set ocorreram no site:33,0%. É um teto técnico por canal, não a fração que clicou num botão. Lojas não expõem a tela à Vitaliza.','Todos os fins pagos jun-set; não apenas base inicial.'),('7. A campanha tem evidência dependente do horizonte.','Cupom: resultado não conclusivo em30dias; até o corte, redução de1,92pp (IC95%0,60–3,24). Benefício estatístico não é comprovação de rentabilidade.','ITT da campanha10/08; análise secundária exploratória.')]
for title,body,src in findings:add(f'<div class="finding"><h3>{title}</h3><p>{body}</p><small>{src}</small></div>')
add(call('Implicação para o Artefato 1','A entrega já suporta segmentação estratégica e personas mensuráveis. Ainda não suporta escolher definitivamente A/B, atribuir causalidade ao preço, afirmar uplift individual ou prometer ROI.','coral'));end()

