add(call('Divergência não implica erro de uma das fontes','Podem ser versões, universos ou marcos diferentes. Fundação e lançamento, por exemplo, não são necessariamente o mesmo evento. Não houve pesquisa externa de mercado para validar captação ou anúncios do Strava; esses elementos permanecem contexto narrativo. O orçamento estratégico de R$600mil não substitui automaticamente o limite operacional mensal de R$40mil.'))
add('''<div class="table-wrap"><table><tr><th>Item da aula</th><th>O que o dado permite</th><th>Tratamento</th></tr><tr><td>349/1.060 sem clique</td><td>Não há log de clique; existe canal e evento de assinatura.</td><td>Não verificável exatamente; não inferir clique pela loja.</td></tr><tr><td>320 assinantes de baixo uso</td><td>Regra explícita dá2.440 no último mês;1.015 persistentes.</td><td>Denominador, data e definição diferentes.</td></tr><tr><td>R$153mil de ARR desses320</td><td>Na regra atual, ARR equivalente≈R$782mil dos2.440.</td><td>Preço e mistura de planos reais; não usar39,90 para todos.</td></tr><tr><td>Early Droppers33%, Desengajados14%, Sleeping Dogs8%</td><td>Os três segmentos estatísticos não reproduzem essa taxonomia.</td><td>Comparar mecanismos, não forçar percentuais.</td></tr></table></div>''');end()

