add(figs['revenue']);add(evidence('receita_mensal_proxy','Somente meses com preço disponível para100% da base inicial; MRR=última cobrança positiva normalizada pelo plano, não receita contábil.'))
add('<details><summary>Perfil dos pagantes no corte: demografia, planos, canais e aquisição</summary>'+tab(D['perfil_corte'],pc=['share'])+tab(D['resumos_corte'])+'</details>')
add('''<p>57,47% dos pagantes estão no anual. O sexo informado foi padronizado, não inferido;4,74% não informado. Demografia descreve o corte atual, não foi usada no clustering nem retroprojetada para os modelos históricos. Idade mediana válida≈47anos, com13.856 registros plausíveis.</p>''')
add('<h3>Abandono inicial: hipótese passível de refutação</h3>'+figs['early']);add(evidence('abandono_inicial','19.967 novas assinaturas de01/2025 a31/07/2026, todas com60dias observáveis. Janela2 usa apenas sobreviventes da1; não é teste de duas amostras independentes.'))
add('<h3>Retenção por safra, com censura</h3>'+figs['km']);add(evidence('retencao_KM','Coortes incidentes desde01/2025, censuradas no encerramento de30/09/2026. Pontos com<50em risco ocultados; não há IC nesta visualização.'))
add(call('Leitura correta da curva','Kaplan–Meier mantém usuários censurados no risco até o fim de sua observação; não os trata como se nunca fossem sair. A curva compara safras com idades e calendários diferentes e não ajusta mix de plano/canal. É descritiva, não evidência de que uma safra é intrinsecamente melhor.'));end()

begin('behavior','05 · CUSTOMER BEHAVIOR','Comportamento recente: sinal útil, explicação incompleta','Aprofundamos um único landmark para evitar tratar meses repetidos da mesma pessoa como amostras independentes:14.032 pagantes ao encerrar31/07/2026; perda observada entre01/08 e29/09 (60dias).')
add('''<div class="timeline"><div><b>Maio–junho</b><span>Referência de tendência.</span></div><i>→</i><div><b>Julho</b><span>Sessões, mix e sinais.</span></div><i>→</i><div><b>01/08–29/09</b><span>Desfecho de60dias.</span></div><i>→</i><div><b>30/09</b><span>Aplicação dos perfis, sem alvo futuro.</span></div></div>''')
add(tab(D['testes_naoparametricos']))
add(evidence('testes_naoparametricos','Mann–Whitney bilateral, efeito rank-biserial e BH nesta família de5testes; sem equivalência a causalidade ou desempenho preditivo.'))
add('''<p>Quem saiu tinha mediana de <b>0,68 sessão/semana</b>, contra <b>1,35</b> entre quem não saiu. A mediana do intervalo entre treinos no corte atual é1,90dia entre12.212 com múltiplas atividades nos30dias anteriores; não se aplica a quem não treinou ou só teve um registro.</p>''')
add('<h3>O ajuste muda a interpretação da queda de uso</h3>'+figs['nested'])
add(call('Revisão metodológica que mudou a estimativa','3.112 casos não têm comparação válida para queda(percentual com base zero/ausente ou uso recente ausente). Eles foram separados na tabela e no modelo, em vez de misturados com quem não teve queda. Entre2.275 com queda50, o churn60 é16,97%; entre8.645 comparáveis sem queda,6,42%. Essa decisão de denominador é material.'))
add(tab(D['taxa_queda50'],pc=['churn','ic95_inf','ic95_sup']))
add(call('Não confundir “sumiu no ajuste” com “não importa”','A OR de queda≥50% passa de3,79 (plano, tenure, canal e indicador de comparação inválida) para2,74 (+engajamento e sinais) e1,68 (+estado de renovação). A associação permanece positiva, comIC95%1,38–2,04 no modelo completo. O aviso de desligamento pode capturar a mesma trajetória de saída ou mediar parte dela. Não estabelecemos um grafo causal nem a temporalidade interna entre queda e aviso; o ajuste completo <b>não refuta o uso como sinal antecedente</b>, nem identifica seu efeito causal.','coral'))
add('<details><summary>Especificações e efeitos condicionais: o que exatamente foi ajustado?</summary><p>Modelo completo: log(1+sessões/semana), queda50, participação de vídeo, recusa30dias, ticket30dias, renovação desligada/desconhecida, log(1+tenure), plano anual, ausência de uso e canal. GLM binomial/logit, erros robustosHC3, uma linha por pessoa. Valores ausentes dos regressores foram imputados pela mediana, com indicador de uso ausente. Casos sem comparação válida de queda(referência zero/ausente ou recente ausente) recebem indicador próprio; não são tratados como não queda comparável. OR não é razão de riscos; aproximações não devem ser extrapoladas. O regime histórico inclui a campanha de agosto.</p>'+tab(D['coef_associacoes'])+tab(D['modelos_aninhados'])+'<p>Sensibilidade de tenure por faixas, referência&gt;365dias. Não são riscos relativos e a forma funcional é exploratória:</p>'+tab(D['tenure_categorico'])+'</details>')
add('<h3>Funcionalidades observáveis — e apenas elas</h3>'+figs['func']);add(evidence('atividades.parquet','1.254.475 treinos de01/01 a30/09/2026, incluindo contas grátis. Usuários por modalidade se sobrepõem.'))
add(call('Não há dados para meditação, nutrição e sono','Não equiparamos yoga a meditação. O diagnóstico de funcionalidade limita-se ao tipo de treino, ao mix vídeo/ar livre e à rede social. Participação de vídeo tem OR0,709 por mudança de0para1 no modelo completo; é associação entre perfis, não prova de que empurrar vídeos reduz churn.'))
add('<details><summary>Redundância: por que não colocar todas as métricas no cluster?</summary>'+figs['corr']+'<p>Sessões e dias ativos têm Spearman≈0,976; atividades e dias≈0,995. Usá-las juntas atribuiria peso duplicado a volume. Removemos dias ativos/minutos/total de atividades do conjunto primário de clustering, mantendo apenas sessões como dimensão de volume. A regressão final apresenta VIFs no arquivo analítico; o maior está nas flags de renovação,≈3,67.</p>'+tab(D['multicolinearidade_VIF'])+'</details>');end()

begin('hypotheses','06 · HYPOTHESIS LAB','14 hipóteses: evidência que pode contrariar o briefing','Os status são exploratórios e condicionados às definições abaixo. “Sustentada como associação” não significa mecanismo causal demonstrado. Os q-valores corrigem famílias declaradas, não toda a exploração do relatório.')
add('''<div class="toolbar"><label>Status<select id="hyp-status"><option value="all">Todos</option><option value="sustentada">Sustentadas</option><option value="contrariada">Contrariadas</option><option value="inconclusiva">Inconclusivas</option><option value="não testável">Não testáveis</option></select></label><label>Pesquisar<input id="hyp-search" placeholder="Ex.: preço, clique, uso, cobrança"></label></div><div id="hyp-list"></div>''')
add(call('O teste precisa corresponder à hipótese','H1 usa incidência paga em janelas de30dias, não a taxa da base já envelhecida. H2 mantém associação ajustada; H3 exige atenção à forma funcional e à oportunidade de renovação. H12 é inconclusiva sobre informação incremental no modelo completo, apesar de relação bruta forte. H8 é não testável exatamente. Isso é parte do resultado, não uma falha a esconder.'));end()

begin('segmentation','07 · SEGMENTATION LAB','Três grupos por parcimônia, não por obrigação de reproduzir os slides','Agrupamos13.653 pagantes com uso recente observado em julho. Os379 sem esse registro foram separados como cobertura insuficiente. A aplicação no corte de setembro utiliza as mesmas transformações e centros — sem refit.')
add('''<div class="two"><div class="card"><h3>Cinco variáveis de agrupamento</h3><ul><li>log(1+sessões/semana): volume.</li><li>Tendência logarítmica recente vs média dos2meses anteriores disponíveis.</li><li>Participação de vídeo no total de atividades.</li><li>log(1+tempo de assinatura).</li><li>log(1+seguidores anteriores à referência).</li></ul><p>Sem churn, intenção de cancelar, preço, suporte, sexo ou idade.</p></div><div class="card"><h3>Pipeline ajustado só em julho</h3><ol><li>Winsorização1–99% por feature.</li><li>Imputação mediana de faltantes residuais.</li><li>StandardScaler.</li><li>K-Means, k=2…6,15inicializações.</li><li>5reamostragens de80% sem reposição por k.</li></ol><p>Sem meses anteriores para tendência, imputa-se a mediana de julho; não zero. Não é bootstrap clássico nem validação temporal da eficácia.</p></div></div>''')
add(figs['k']);add(tab(D['cluster_metricas']))
add(call('Critério fixado antes de olhar o churn','Soluções elegíveis: todos os grupos≥5% e ARI médio≥0,75. Entre soluções com silhouette a até0,02 da melhor elegível, preferimos k3/4 com menor k. k4 tem silhouette0,239; k3=0,223 entra na tolerância e é mais simples. k3 tem ARI médio0,991. A separação é <b>moderada, não perfeita</b>; estabilidade não prova a existência de classes naturais.'))
add(f'<p>Sensibilidade a recolocar a feature redundante “dias ativos”: ARI={M["redundancia_ARI"]:.3f} com o particionamento primário no mesmo k. Não escolhemos features ou k pelo churn futuro.</p>')
add(call('Estabilidade condicional, não universal','A partição é reamostralmente estável com as cinco features, mas muda bastante quando se inclui dias ativos(ARI≈0,444), muito correlacionado com sessões. O conjunto primário exclui essa redundância por justificativa de peso, não porque o alternativo produz menos churn. As personas são provisórias e precisam de validação temporal e de utilidade.','coral'))
add(figs['centers']);add(evidence('centroides_z','Centros na escala padronizada após winsorização/imputação. Centro negativo não significa valor original negativo.'))
add(figs['pca']);add(evidence('pca_amostra_anonima','2.200 pontos amostrados com seed2026. PCA2D explica '+pct(sum(M['pca_explicado']),1)+' da variância transformada. A projeção não representa toda a distância usada no K-Means.'))
add(figs['segmentloss']);add(evidence('segmentos','Churn60 posterior em julho; IC95%Wilson por grupo. Grupos foram criados sem desfecho; comparação global exploratória, sem teste de efeitos de campanha por cluster.'))
add('<details><summary>Regras de negócio vs agrupamentos</summary><p>Regras mutuamente exclusivas: sem dado recente; entrada≤30dias; baixo uso persistente >180dias; queda50; demais perfis. As regras são mais auditáveis; clusters capturam combinação de nível, tendência, mix, ciclo e rede. Nenhuma abordagem mede persuasão.</p>'+tab(D['regras_vs_clusters'])+tab(D['regras_julho'],pc=['churn','ic95_inf','ic95_sup'])+'</details>')
add('''<h3>Comparação com a taxonomia da aula</h3><ul><li><b>Early Droppers:</b> S2 tem ciclo jovem, mas mediana63dias e uso crescente; não é equivalente a abandono nos primeiros30dias.</li><li><b>Desengajados:</b> S1 tem baixo uso e retração, mas inclui maioria anual e tenures longos; não reproduz o percentual14%.</li><li><b>Sleeping Dogs:</b> baixo uso persistente é regra transversal. Identificar dano causado por contato exigiria evidência experimental específica, não apenas frequência baixa.</li></ul>''');end()

begin('personas','08 · DATA-DRIVEN PERSONAS','Personas que orientam investigação, sem inventar motivações','As características comportamentais abaixo vêm do landmark de julho; tamanho e receita atuais vêm da aplicação em setembro. Não misturamos os dois cortes como se fossem a mesma população.')
actions={'S1':('Investigar adequação de rotina e barreiras de uso; revisar renovação anual e cobrança.','Abordagem pode lembrar assinatura pouco usada; não há evidência de benefício do contato nesse grupo.'),'S2':('Investigar ativação e formação de hábito; testar orientação sem subsídio amplo.','Confundir pouco tempo de casa com fracasso; abordar antes de a pessoa completar adaptação.'),'S3':('Preservar experiência e conteúdo; investigar problemas pontuais, não disparar cupom geral.','Subsidiar quem ficaria de qualquer maneira; alto valor agregado não implica alto uplift.')}
for i,r in P[P.segmento.ne('Sem dado recente')].iterrows():
 a,b=actions[r.segmento];share=r.mrr_setembro/M['mrr_proxy']
 add(f'''<article class="persona" style="--accent:{colors[i]}"><div class="persona-head"><span>{r.segmento}</span><h3>{names[r.segmento]}</h3><b>{n(r.n_setembro)} pagantes atuais · {pct(r.share_setembro,2)}</b></div><div class="persona-grid"><div><small>CHURN60 OBSERVADO · JULHO</small><b>{pct(r.churn60,2)}</b><span>{n(r.perdas60)} / {n(r.n_julho)} · IC95%{pct(r.ic95_inf,1)}–{pct(r.ic95_sup,1)}</span></div><div><small>SESSÕES/SEMANA · MEDIANA</small><b>{r.sessoes_semana_mediana:.2f}</b><span>Atividades/mês: mediana{r.atividades_mediana:.0f}.</span></div><div><small>TEMPO DE CASA · MEDIANA</small><b>{r.tenure_mediano:.0f} dias</b><span>{pct(r.pct_anual,1)} anual no landmark.</span></div><div><small>MRR EQUIVALENTE · SETEMBRO</small><b>{brl(r.mrr_setembro)}</b><span>{pct(share,1)} da receita proxy atual.</span></div></div><p><b>Mix mensurável:</b> vídeo médio{pct(r.video_share_medio,1)}; mediana de seguidores{r.seguidores_mediana:.0f}; tendência log mediana{r.trend_mediana:.3f}.</p><p><b>Hipótese de investigação:</b> {a}</p><p><b>Risco de intervir:</b> {b}</p><p class="evidence">MRR exposto por transferência de taxa histórica: {brl(r.mrr_exposto_proxy)}. Não é receita recuperável nem previsão individual calibrada.</p></article>''')
add(call('O grupo sem dado não é uma quarta persona','379 no landmark,340 no corte atual; churn60 histórico19,79%, com incerteza maior. O MRR atual equivalente é'+brl(float(P.loc[P.segmento.eq('Sem dado recente'),'mrr_setembro'].iloc[0]))+'. Prioridade é investigar captura/cobertura. Não rotular ausência de BI como inatividade ou construir uma história psicológica.','coral'));end()

begin('risk','09 · RISK × VALUE MATRIX','Prioridade de investigação não é aprovação de campanha','O eixo de risco é uma frequência futura observada na população de julho. O eixo de valor é o MRR equivalente da população de setembro. São cortes distintos, explicitamente combinados apenas como diagnóstico preliminar.')
add(figs['risk']);add(evidence('segmentos','Bolha proporcional de forma ilustrativa ao tamanho atual; risco histórico comIC na tooltip. Não há uplift individual nem risco individual calibrado.'))
add(tab(P[['segmento','n_setembro','churn60','mrr_setembro','mrr_exposto_proxy','contrib_setembro']],pc=['churn60'],money=['mrr_setembro','mrr_exposto_proxy','contrib_setembro']))
add('''<div class="table-wrap"><table><tr><th>Conceito</th><th>Definição utilizada</th><th>O que não significa</th></tr><tr><td>Risco observado</td><td>Fração de julho que expirou em60dias.</td><td>Probabilidade individual atual.</td></tr><tr><td>Risco estimado</td><td>Transferir a taxa do segmento sob hipótese de estabilidade.</td><td>Modelo preditivo validado.</td></tr><tr><td>Receita da população</td><td>MRR equivalente atual somado.</td><td>Receita em risco inteira.</td></tr><tr><td>Receita exposta proxy</td><td>MRR setembro × churn60 do segmento julho.</td><td>Caixa perdido nos60dias ou perdas garantidas.</td></tr><tr><td>Receita preservável</td><td>Exigiria efeito causal incremental × receita/margem no horizonte.</td><td>Toda a receita exposta.</td></tr></table></div>''')
add('''<h3>Classificação preliminar</h3><div class="three"><div class="card"><h3>S1 · investigação elevada</h3><p>Maior risco histórico dos clusters, receita material e baixo uso. Potencial de retenção não demonstrado; risco de contato contraproducente permanece hipótese.</p></div><div class="card"><h3>S2 · oportunidade a testar</h3><p>Ciclo jovem e crescente; estudar ativação e adequação. Não tratá-lo como Early Dropper automaticamente.</p></div><div class="card"><h3>S3 · preservar valor</h3><p>Maior receita agregada e menor risco histórico. Testar seletividade; não oferece evidência para descontos em massa.</p></div></div>''')
add(call('Incerteza da transferência','A mistura de planos e tenures pode mudar dentro de cada grupo. A campanha já afetou parte da janela de julho. Somar MRR×taxa não captura proximidade da renovação anual, intensidade de receita ou tratamento individual. Os intervalos dos riscos históricos não cobrem a incerteza adicional da transferência temporal.'));end()

begin('finance','10 · FINANCIAL INTELLIGENCE','Reconciliar dinheiro antes de prometer retorno','Não confundimos cobrança anual recebida com receita recorrente mensal. Os valores equivalentes usam a última cobrança aprovada positiva conhecida no corte; anuidades são divididas por12.')
add(tab(D['financeiro_reconciliacao']))
add(f'''<div class="kpis"><div><small>MRR BRUTO · PROXY</small><b>{brl(M['mrr_proxy'])}</b><span>Ticket equivalente {brl(M['mrr_proxy']/M['corte_n'])}.</span></div><div><small>ARR EQUIVALENTE</small><b>{brl(M['arr_proxy'])}</b><span>12×MRR; não anual realizado.</span></div><div><small>LÍQUIDO APÓS CANAIS</small><b>{brl(M['mrr_net_proxy'])}</b><span>Taxas do enunciado.</span></div><div><small>CONTRIBUIÇÃO · PROXY</small><b>{brl(M['contrib_proxy'])}</b><span>Líquido −R$4,20 por pagante.</span></div></div>''')
add('''<p><b>Cobertura:</b> todos os14.753 atuais têm cobrança positiva anterior; nenhum fallback de preço foi necessário no corte. Isso não elimina limitações: a última cobrança pode não refletir descontos futuros, reconhecimento contábil ou obrigação de meses grátis. O MRR perdido de setembro éR$23.344,22 da base inicial; churn de receita equivalente5,28%, diferente de4,99% de churn de clientes.</p>''')
add('<details><summary>Coerência interna dos números da aula e LTV/CAC</summary><p>27.901×39,90×12=R$13.359.000aproximadamente, coerente comARR13,35mi por arredondamento. R$113.500÷(27.901×39,90)≈10,20%. O churn anualizado de10,2%mensal é1−(1−0,102)^12≈72,5%, próximo dos73% narrados; depende de constância e não é churn anual observado.</p><p>O CAC médioR$118 e as taxas/custos do enunciado estão disponíveis. Não há CAC por coorte/canal nem vida futura completa. Uma aproximação geométrica “margem mensal÷churn÷CAC” exigiria churn constante, horizonte e margem estáveis, ausência de censura relevante e compatibilidade com anuais. Por isso <b>LTV/CAC2,02x não foi confirmado nem substituído por um número aparentemente preciso</b>.</p><p>O fluxo de cobranças aprovadas e ajustes negativos foi somado separadamente nas tabelas reutilizáveis. Não foi chamado de receita reconhecida ou usado para confundir caixa comMRR.</p></details>')
add('<h3>Sensibilidade de uma ação: hipóteses abertas, não eficácia prometida</h3>')
add(f'''<div class="scenario"><div class="controls"><label>Contatados<input id="sc-n" type="number" value="1000" min="1"></label><label>Efeito incremental hipotético (pp)<input id="sc-u" type="number" value="1" step="0.1" min="-100" max="100"></label><label>Canal<select id="sc-c"><option value="0.01">E-mail · R$0,01</option><option value="0.4">WhatsApp · R$0,40</option><option value="18">CS · R$18</option><option value="0">Push · custo desprezível</option></select></label><label>Contribuição preservada por retido (R$)<input id="sc-m" type="number" value="{M['contrib_proxy']/M['corte_n']:.4f}" step="0.1" min="0"></label><label>Oferta esperada por contatado (R$)<input id="sc-o" type="number" value="0" step="0.1" min="0"></label><label>IA por contatado · hipotético (R$)<input id="sc-i" type="number" value="0" step="0.01" min="0"></label></div><div id="sc-result"></div><small>Efeito1pp e custos de oferta/IA são hipóteses editáveis. Zero não comprova ausência real de custo. A contribuição padrão é a média equivalente deum mês no corte; nenhuma permanência adicional é garantida.</small></div>''')
add('<details><summary>Ver cenários fixos executados e salvos</summary>'+tab(D['sensibilidade'],money=['margem_mes_por_retido','contribuicao_1mes','custo_contato','saldo_hipotetico'])+'<p>Todos usam1.000contatos, margem média deum mês, efeito assumido0,5/1/2pp e custo direto de oferta/IA assumidozero. Não representam resultado esperado ou ROI observado da Vitaliza.</p></details>')
add(call('Não multiplicar “quem ficou” pela receita','O benefício vem de quem ficou por causa da ação, não de todos os retidos. Descontos a quem ficaria sem contato também custam. Para orçamento, despesas e obrigações de ofertas precisam ser distribuídas no calendário correto; não aprovamos campanhas com base apenas neste cenário.','coral'));end()

begin('executives','11 · EXECUTIVE ASSUMPTIONS UNDER TEST','Quatro posições: nenhuma ganha por narrativa','A matriz usa as premissas recebidas no briefing, não depoimentos verificados dos executivos. A comparação prepara a decisão, não escolhe A ou B.')
execs=pd.DataFrame([
 ['Patrícia · CS','A pode recuperar no cancelamento','Clique/tela, elegibilidade, oferta, resgate e grupo de controle','Site responde por33,0% dos fins jun-set; lojas≈67,0%','Telemetria de clique não existe; alcance efetivo e uplift do fluxo não medidos'],
 ['Marcelo · Produto','B detecta desengajamento antes da saída','Sinais antecedentes e validação temporal do risco','Sessões, recusas e avisos anteriores se associam a perda; queda é sensível ao ajuste','Modelo fora do tempo, engenharia de features e teste de política; correlação não é viabilidade'],
 ['Diego · CTO','Infraestrutura pode limitar a implantação','Latência, IDs, qualidade, cobertura, custo e operação','Fusos e formatos heterogêneos; sem evento_id/assinatura_id;340 sem uso recente no corte','SLA/latência, completude, custos reais de pipeline e mapeamento de múltiplos ciclos'],
 ['Rita · CFO','Retenção precisa provar valor líquido','Margem incremental, oferta, resgate, horizonte e custo','MRR e contribuição equivalentes calculáveis; efeito médio da campanha depende da janela','ROI realizado, resgate, benefício por segmento, permanência e custo de IA']
 ],columns=['Executivo','Premissa','Evidencia_necessaria','Dataset','Falta']);add(tab(execs))
add('<h3>Há tempo para agir entre o sinal e o fim?</h3>'+tab(D['antecedencia_sinal']))
add(evidence('Eventos de desligamento anteriores à expiração','Somente fins jun-set com aviso anterior encontrado; usa último aviso encontrado, não exclui religamentos intermediários; mediana não vale para todos os cancelamentos.'))
add(call('Antecedência útil, com limite','Entre os casos com sinal, as medianas são≈22dias nas lojas. Isso justifica investigar intervenções no intervalo, mas não prova que os casos estavam elegíveis ou persuadíveis em cada dia. A reconstrução fina do estado de renovação ainda deve validar desligar/religar e o acesso no instante da ação.'))
add('<h3>Experimento existente: nem efeito médio é igual a recomendação</h3>'+figs['campaign']);add(evidence('Campanha de10/08','ITT30dias e até corte; IC95% para diferenças. Não mede cancelamento na tela, nem o efeito separado de WhatsApp/CS.'))
add('<details><summary>Sleeping Dogs: o experimento prova dano em quem usa pouco?</summary>'+tab(D['experimento_baixo_uso'],pc=['churn'])+'<p>Subgrupo exploratório definido pelo baixo uso persistente de julho, intersectado com sorteados de agosto: controle230, demais braços≈222–245. As taxas pontuais não foram convertidas em conclusão causal confirmatória; sem pré-especificação, com amostras pequenas e seleção para estar ativo em10/08, este quadro não demonstra dano de contato nem benefício de mensagem individual. Requer teste direcionado e poder amostral.</p></details>');end()

