begin('roadmap','13 · ROADMAP FOR CLASS 2','Do diagnóstico ao Customer Segmentation Analysis Report','A sequência mantém abertas as alternativas A e B, mas torna as próximas decisões testáveis.')
lists=[('A · Cinco descobertas para discutir',[
 'A divergência aula/data room muda a escala econômica e não pode ser resolvida por assumir que um deles está errado.',
 'A concentração nos primeiros30dias pagos foi contrariada; a definição de early drop precisa ser debatida.',
 'A queda de uso mantém associação, mas seu efeito condicional é atenuado pelo aviso de renovação; mediação/redundância são alternativas não provadas.',
 'Três segmentos estáveis à reamostragem são úteis, mas a escolha de features altera a partição; não equivalem a classes naturais nem aos rótulos dos slides.',
 'Baixo uso persistente é material; os dados ainda não mostram quem é prejudicado por contato.'
 ]),('B · Cinco perguntas para a Aula 2',[
 'Qual versão, data de corte e universo devem orientar os KPIs oficiais do Artefato1?',
 'Como definir abandono precoce: trial, primeiros30dias pagos ou tempo até a primeira renovação?',
 'O aviso de renovação desligada é sinal operacional elegível ou variável que queremos excluir para prever risco silencioso?',
 'Qual critério de utilidade de segmentos pesa mais: separação geométrica, estabilidade ou decisão testável?',
 'Qual horizonte econômico, elegibilidade e métrica serão pré-especificados para comparar A e B?'
 ]),('C · Cinco análises com maior potencial de mudar o entendimento',[
 'Sobrevivência condicionada à oportunidade de renovação mensal/anual e ao fim do cupom de primeiro ano.',
 'Validação temporal de modelos com/sem avisos explícitos, separando risco silencioso de intenção declarada.',
 'Reconciliação BI×treinos e estudo dos340 sem registro recente, sem imputar zero.',
 'Experimento pré-registrado de ações por segmento com retorno líquido, resgate e teste de dano.',
 'Estabilidade de clusters em novas safras e comparação com regras e alternativas de distância/algoritmo.'
 ]),('D · Sequência analítica até o Artefato 1',[
 'Fixar escopo oficial e dicionário de métricas com o professor; registrar versões e premissas.',
 'Validar intervalos/eventos, carência, perda efetiva e dados disponíveis na data.',
 'Consolidar features robustas, critérios de segmentação e sensibilidade; evitar redundância.',
 'Validar perfis em cortes temporais adicionais; documentar tamanho, estabilidade, churn e valor por coorte.',
 'Finalizar personas mensuráveis, mapa de investigação e plano de experimento — sem prometer ganho não identificado.'
 ])]
for title,items in lists:add('<div class="road-card"><h3>'+title+'</h3><ol>'+''.join('<li>'+v+'</li>' for v in items)+'</ol></div>')
add('''<h3>Explore os resultados agregados e reutilize as evidências</h3><div class="toolbar"><label>Tabela<select id="table-select"></select></label><label>Filtro<input id="table-search" placeholder="Pesquisar registros…"></label><button id="csv">Exportar CSV filtrado</button></div><p id="table-count" class="evidence"></p><div id="table-content"></div><p class="evidence">Nos dados brutos das tabelas, churn/share/retencao são frações (0,05=5%); pp já estão em pontos percentuais. Valores do landmark e do corte atual são rotulados. Quantidades de usuários não devem ser somadas entre modalidades nem entre meses.</p>''')
add('''<h3>Trilha de reprodução e referências</h3><p><b>Fontes:</b> enunciado/dicionário fornecidos;12arquivos de dados brutos; resultados anteriores conferidos; briefing V2 recebido como narrativa. Não há slides originais, imagens ou pesquisa externa de mercado confirmada.</p><p><b>Artefatos derivados:</b> tabelas de auditoria, features por usuário e data, hipóteses, modelos associativos, transformação de clusters, diagnóstico financeiro e código são salvos junto ao relatório. Não foram incorporados e-mails ou textos livres pessoais no HTML; a amostraPCA não contém IDs.</p><p><b>Regra de rastreabilidade:</b> resultados numéricos remetem às tabelas com o mesmo nome no explorador e à planilha exportada. O protocolo explica janelas, imputação, seleção de k, testes e limitações. Q-BH por família declarada não torna o estudo confirmatório. Seeds e dependências são registradas para reprodução.</p><p><b>Critério de revisão:</b> hipótese não testável permanece não testável; cenário permanece cenário; persona permanece descrição de variáveis. A análise não escolhe vencedor entre A e B.</p>''');end()

CSS='''
:root{--teal:#116e69;--deep:#34204e;--coral:#ed7c6a;--ink:#243943;--muted:#64777f;--bg:#f3f6f5;--line:#dce5e3;--side:240px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.75 Arial,sans-serif}a{color:var(--teal)}aside.nav{width:var(--side);position:fixed;inset:0 auto 0 0;background:#123c3c;color:#b9d4d1;padding:28px 17px;overflow:auto;z-index:30}.brand{font-size:28px;font-weight:800;color:white;letter-spacing:-1px}.brand em{color:#ef9b85;font-style:normal}.nav small{font-size:9px;letter-spacing:1.6px;display:block;margin:10px 0 24px}.nav a{display:block;color:#bcd2d0;font-size:11px;line-height:1.5;text-decoration:none;padding:10px;border-radius:6px;margin:3px 0}.nav a:hover,.nav a.active{background:#285555;color:white}.nav-bottom{font-size:10px;color:#a6c5c0;border-top:1px solid #396464;padding-top:16px;margin-top:22px}.progress{height:4px;background:#dfe8e5;position:fixed;top:0;left:var(--side);right:0;z-index:50}.progress div{height:100%;background:var(--coral);width:0}main{margin-left:var(--side);max-width:1540px;padding:30px 4vw 70px}.hero{border-radius:18px;background:linear-gradient(120deg,#123f3e 10%,#34204e);padding:46px 40px;color:#fff;margin-bottom:26px}.pill{font-size:10px;letter-spacing:1.4px;border:1px solid #ffffff44;border-radius:20px;padding:7px 12px}.hero h1{font-size:clamp(28px,3.1vw,45px);line-height:1.18;letter-spacing:-1.4px;max-width:970px;margin:24px 0 19px}.hero .subtitle{font-size:14px;color:#c5d9d7}.hero-line{border-top:1px solid #ffffff2c;margin-top:24px;padding-top:20px;font-size:19px;color:#e1e9e7}.hero-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:26px}.hero-tags span{font-size:10px;background:#ffffff13;padding:6px 9px;border-radius:6px}section{background:white;border:1px solid var(--line);border-radius:13px;padding:34px;margin:22px 0;scroll-margin-top:24px}.eyebrow{font-size:10px;color:var(--teal);letter-spacing:1.5px;font-weight:800}h2{font-size:29px;line-height:1.27;letter-spacing:-.7px;margin:12px 0 15px;color:var(--deep)}h3{font-size:18px;line-height:1.5;margin:26px 0 12px}p{margin:12px 0}.lead{font-size:16px;color:var(--muted);max-width:1000px;margin-bottom:25px}.kpis{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:22px 0}.kpis>div{padding:22px;border:1px solid #d7e4df;background:#f6faf8;border-radius:10px}.kpis small{font-size:9px;letter-spacing:1.2px;color:var(--teal);display:block}.kpis b{display:block;font-size:29px;color:var(--deep);line-height:1.3;margin:9px 0}.kpis span{font-size:11px;color:var(--muted)}.finding{border-top:1px solid var(--line);padding:17px 0}.finding h3{margin:0 0 8px}.finding small,.evidence{font-size:11px;color:var(--muted);line-height:1.6}.evidence{padding:10px 0}.callout{padding:20px 23px;border-radius:8px;border-left:4px solid var(--teal);background:#eef7f3;margin:23px 0;font-size:14px}.callout b{color:#175d58}.callout p{margin:7px 0 0}.callout.coral{background:#fff1ed;border-color:var(--coral)}.coral b{color:#a34c3d}.two,.three{display:grid;gap:16px;margin:23px 0}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.card{border:1px solid var(--line);background:#f7f9f8;padding:20px;border-radius:9px;font-size:13px}.card h3{margin-top:0;font-size:16px}.card ul,.card ol{padding-left:18px}.table-wrap{border:1px solid var(--line);border-radius:9px;overflow:auto;max-height:560px;margin:18px 0}table{border-collapse:collapse;width:100%;font-size:11px;line-height:1.65}th,td{padding:11px 13px;border-bottom:1px solid var(--line);vertical-align:top;min-width:85px}th{position:sticky;top:0;background:#eaf0ee;color:#37564f;text-align:left;font-weight:bold;z-index:2;white-space:nowrap}tr:nth-child(even) td{background:#f9fbfa}details{border:1px solid var(--line);padding:16px 18px;border-radius:8px;margin:16px 0;font-size:13px}summary{cursor:pointer;color:var(--deep);font-weight:700}details[open] summary{margin-bottom:15px}.flow,.timeline{display:flex;gap:8px;margin:24px 0;align-items:stretch}.flow span,.timeline div{flex:1;padding:15px 12px;background:#f2f6f4;border:1px solid #dbe6e1;border-radius:7px;font-size:12px}.timeline span{display:block;font-size:11px;color:var(--muted);margin-top:6px}.flow i,.timeline i{align-self:center;color:#7a9890;font-style:normal}.toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap;padding:16px;background:#f5f8f6;border-radius:9px;margin:18px 0}label{font-size:11px;color:#536c67;font-weight:bold;display:flex;flex-direction:column;gap:6px}.toolbar label{flex:1;min-width:180px}input,select{width:100%;border:1px solid #cad9d3;border-radius:6px;font:13px Arial,sans-serif;background:white;padding:11px;color:var(--ink);min-width:0}input:focus,select:focus{outline:2px solid #a8cfc1}button{background:var(--teal);color:white;border:0;border-radius:6px;padding:12px 15px;font-weight:bold;font-size:11px;cursor:pointer}.hyp{border:1px solid var(--line);border-left:4px solid var(--teal);border-radius:8px;padding:19px;margin:14px 0}.hyp h3{margin:0 0 10px}.hyp .badge{font-size:9px;padding:5px 8px;border-radius:5px;background:#e1eee8;color:#1c6152;display:inline-block;margin-bottom:6px}.hyp.bad{border-left-color:var(--coral)}.hyp.bad .badge{background:#fce4dd;color:#a25244}.hyp.open{border-left-color:#b59b59}.hyp.open .badge{background:#faf1d9;color:#80682e}.hyp-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;font-size:12px}.hyp-grid b{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:5px}.hyp-result{background:#f4f7f6;padding:13px;margin-top:13px;font-size:13px}.persona{border:1px solid var(--line);border-top:5px solid var(--accent);border-radius:11px;padding:25px;margin:22px 0}.persona-head span{font-size:11px;color:var(--accent);font-weight:800}.persona-head h3{font-size:24px;margin:5px 0 12px;color:var(--deep)}.persona-head>b{font-size:13px}.persona-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:19px 0}.persona-grid div{background:#f6f8f7;padding:17px;border-radius:7px}.persona-grid small{font-size:9px;color:var(--muted);display:block}.persona-grid b{font-size:24px;display:block;color:var(--accent);margin:8px 0}.persona-grid span{display:block;font-size:10px;color:var(--muted)}.persona>p{font-size:13px}.scenario{border:1px solid #cfbfdf;background:#f8f5fb;border-radius:10px;padding:22px}.controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}#sc-result{padding:20px 0;font-size:16px}#sc-result b{font-size:26px;color:var(--deep)}.scenario small{font-size:11px;color:var(--muted)}.road-card{border-bottom:1px solid var(--line);padding:14px 0}.road-card li{padding:6px 0}.print{position:fixed;right:16px;bottom:16px;z-index:35;background:var(--deep)}.footer{text-align:center;color:var(--muted);font-size:11px;padding:20px}.plotly-graph-div{max-width:100%}.modebar{opacity:.5}
@media(max-width:1100px){:root{--side:200px}main{padding:20px}section{padding:26px}.hero{padding:35px 28px}.three{grid-template-columns:1fr}.flow{flex-wrap:wrap}.flow span{min-width:110px}}@media(max-width:740px){:root{--side:0px}aside.nav{display:none}main{padding:12px;margin:0}.hero{padding:30px 21px}.hero h1{font-size:31px}.hero-line{font-size:17px}section{padding:24px 18px}h2{font-size:25px}.two,.kpis,.controls,.hyp-grid{grid-template-columns:1fr}.timeline{flex-direction:column}.timeline i{transform:rotate(90deg)}.persona{padding:20px}.persona-grid{grid-template-columns:1fr}.persona-grid b{font-size:25px}.table-wrap{max-height:500px}.kpis b{font-size:29px}}@media print{.nav,.progress,.print{display:none!important}main{margin:0;padding:0;max-width:none}body{background:white;font-size:11px}.hero{-webkit-print-color-adjust:exact;print-color-adjust:exact}section{border:0;padding:20px 0;break-inside:auto}h2,h3{break-after:avoid}.table-wrap{max-height:none;overflow:visible}tr,.persona,.callout,.hyp,.plotly-graph-div{break-inside:avoid}.toolbar{display:none}.kpis{grid-template-columns:repeat(2,1fr)}}
'''
JS='''
const DB=__JSON__;
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=2)=>Number(x).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
function hypotheses(){let s=document.getElementById('hyp-status').value,q=document.getElementById('hyp-search').value.toLocaleLowerCase('pt-BR');let rows=DB.hipoteses.filter(r=>(s==='all'||r.status.toLocaleLowerCase('pt-BR').includes(s))&&Object.values(r).some(v=>String(v).toLocaleLowerCase('pt-BR').includes(q)));document.getElementById('hyp-list').innerHTML=rows.map(r=>{let type=r.status.toLowerCase().includes('contrariada')?'bad':r.status.toLowerCase().includes('sustentada')?'':'open';return `<article class="hyp ${type}"><span class="badge">${esc(r.status)}</span><h3>${esc(r.id)} · ${esc(r.pergunta)}</h3><div class="hyp-grid"><div><b>Mecanismo proposto</b>${esc(r.mecanismo)}</div><div><b>Variáveis</b>${esc(r.variaveis)}</div><div><b>Método executado</b>${esc(r.metodo)}</div><div><b>Limite da conclusão</b>${esc(r.limitacoes)}</div></div><div class="hyp-result"><b>Resultado:</b> ${esc(r.evidencia)}<p><b>Interpretação:</b> ${esc(r.interpretacao)}</p></div><p class="evidence">n=${fmt(r.n_observacoes,0)} · ${esc(r.periodo)}</p></article>`}).join('')||'<p>Nenhuma hipótese no filtro.</p>'}
document.getElementById('hyp-status').addEventListener('change',hypotheses);document.getElementById('hyp-search').addEventListener('input',hypotheses);hypotheses();
function scenario(){let v=id=>+document.getElementById(id).value,N=v('sc-n'),u=v('sc-u')/100,c=v('sc-c'),m=v('sc-m'),o=v('sc-o'),ia=v('sc-i');let cost=N*(c+o+ia),benefit=N*u*m,net=benefit-cost;let warns=[];if(c===.4&&N>1500)warns.push('Excede capacidade de WhatsApp(1.500/mês).');if(c===18&&N>300)warns.push('Excede capacidade deCS(300/mês).');if(cost>40000)warns.push('Excede orçamento operacionalR$40mil/mês.');let valid=N>0&&Math.abs(u)<=1&&m>=0&&o>=0&&ia>=0;document.getElementById('sc-result').innerHTML=valid?`<b>${fmt(N*u,1)}</b> retidos incrementais hipotéticos<br>Contribuição: R$${fmt(benefit)} · Custo: R$${fmt(cost)}<br>Saldo: <b style="color:${net>=0?'#116e69':'#b35e4d'}">R$${fmt(net)}</b><br><small>ROI apenas do cenário: ${cost>0?fmt(100*net/cost)+'%':'indefinido (custo assumidozero)'} · ${warns.length?warns.join(' '):'Dentro dos limites quantitativos informados, sem validar elegibilidade ou eficácia.'}</small>`:'Confira as hipóteses: quantidades positivas, custos não negativos e efeito entre−100 e+100pp.'}
['sc-n','sc-u','sc-c','sc-m','sc-o','sc-i'].forEach(id=>document.getElementById(id).addEventListener('input',scenario));scenario();
const tableNames=Object.keys(DB).filter(k=>Array.isArray(DB[k])&&k!=='pca');let sel=document.getElementById('table-select'),rows=[];tableNames.forEach(k=>{let o=document.createElement('option');o.value=k;o.textContent=k;sel.appendChild(o)});sel.value='segmentos';
function renderTable(){let q=document.getElementById('table-search').value.toLocaleLowerCase('pt-BR');rows=DB[sel.value].filter(r=>Object.values(r).some(v=>String(v??'').toLocaleLowerCase('pt-BR').includes(q)));document.getElementById('table-count').textContent=`${sel.value}: ${rows.length} de${DB[sel.value].length} linhas. Nenhum dado é recalculado ao filtrar.`;let keys=Object.keys(rows[0]||{});document.getElementById('table-content').innerHTML=rows.length?'<div class="table-wrap"><table><thead><tr>'+keys.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+keys.map(k=>'<td>'+esc(typeof r[k]==='number'?(r[k]!==0&&Math.abs(r[k])<.0001?r[k].toExponential(3):fmt(r[k],Number.isInteger(r[k])?0:6)):r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'<p>Nenhum registro.</p>'}
sel.addEventListener('change',renderTable);document.getElementById('table-search').addEventListener('input',renderTable);renderTable();document.getElementById('csv').addEventListener('click',()=>{if(!rows.length)return;let ks=Object.keys(rows[0]),c=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let text='\\ufeff'+[ks.map(c).join(';'),...rows.map(r=>ks.map(k=>c(r[k])).join(';'))].join('\\r\\n');let url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=sel.value+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
addEventListener('scroll',()=>{let t=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress div').style.width=(t>0?scrollY/t*100:0)+'%'},{passive:true});const ob=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-10% 0px -75% 0px'});document.querySelectorAll('section').forEach(s=>ob.observe(s));document.getElementById('print').addEventListener('click',()=>print());document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)setTimeout(()=>d.querySelectorAll('.js-plotly-plot').forEach(g=>Plotly.Plots.resize(g)),80)}));
'''.replace('__JSON__',json.dumps(J,ensure_ascii=False).replace('</','<\\/'))
nav=[('summary','01 · Executive Summary'),('dilemma','02 · O dilema e as narrativas'),('readiness','03 · Data Readiness'),('performance','04 · Business Performance'),('behavior','05 · Customer Behavior'),('hypotheses','06 · Hypothesis Lab'),('segmentation','07 · Segmentation Lab'),('personas','08 · Data-Driven Personas'),('risk','09 · Risk × Value'),('finance','10 · Financial Intelligence'),('executives','11 · Premissas sob teste'),('unknown','12 · O que não sabemos'),('roadmap','13 · Roadmap para Aula2')]
